#include "eips_private.h"
#include "cmd.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void eips_shutdown_check_timeout_stop(void)
{
  if(!timeout_test(eips_vars.timeout_shutdown_check))
    {
      timeout_stop(eips_vars.timeout_shutdown_check) ;
      
      #if DBG_EIPS == 1
        dbg_tx_text("\nEIPS Check Timeout Stop")  ;
      #endif
      
      cmd_q_insert(INPUT_EIPS_SHUTDOWN_FAIL, COMMAND_INSERT_TIMEOUT);
    }
}
